return async function publishRange(first, end) {
  const h = new Function("tools","store","load",load("v119.publish.helper"))(tools,store,load);
  const root = "/workspace/scratch/dda74a4fae35/v121-selfhost-small-constant-r1/handoff-c0-completed-r1";
  const pub = h.makeHelper(root,"v121.c0.completed.publish.state");
  const rows = load("v121.c0.completed.plan");
  async function readPinned(row, index) {
    const cached = load("v121.c0.completed.pending_text." + index);
    if (typeof cached === "string") {
      if (h.utf8(cached).length !== row.bytes) throw Error("cached byte count differs");
      return cached;
    }
    const py = "import pathlib,json,hashlib,sys;b=pathlib.Path(sys.argv[1]).read_bytes();print(json.dumps({'text':b.decode('utf-8'),'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest(),'git_blob':hashlib.sha1(b'blob '+str(len(b)).encode()+b'\\0'+b).hexdigest()}))";
    const r = await tools.exec_command({cmd:"python -B -c "+h.quote(py)+" "+h.quote(row.local_path),
      shell:"/bin/bash",login:false,workdir:"/",max_output_tokens:120000});
    if (r.exit_code !== 0) throw Error("read failed before POST");
    const value = JSON.parse(r.output);
    if (value.bytes !== row.bytes || h.utf8(value.text).length !== row.bytes ||
        value.sha256 !== row.sha256 || value.git_blob !== row.git_blob)
      throw Error("immutable part full read identity differs before POST");
    return value.text;
  }
  for (let start=first;start<end;start+=2) {
    const selected=rows.slice(start,Math.min(start+2,end));
    await pub.save("scheduler-r2-batch-"+start+"-intent.json",{first:start,count:selected.length,maximum_in_flight:2,paths:selected.map(x=>x.path)});
    const done=await Promise.allSettled(selected.map(async(row,offset)=>
      pub.publish(row.name,await readPinned(row,start+offset),row)));
    store("v121.c0.completed.batch."+start,done);
    await pub.save("scheduler-r2-batch-"+start+"-result.json",done.map(x=>x.status==="fulfilled"?x:{status:x.status,reason:String(x.reason)}));
    text({first:start,results:done.map(x=>x.status==="fulfilled"?{status:x.status,path:x.value.path,git_blob:x.value.git_blob}:{status:x.status,reason:String(x.reason)})});
    if(done.some(x=>x.status!=="fulfilled"))throw Error("batch incomplete; stopped after awaiting both; no retry");
  }
}
